// Generated by `factory render`. Do not edit.
// Parser for `dotnet list <solution> package --vulnerable --include-transitive --format json`: one finding per project,
// package and advisory, identified by the advisory and the package (not its version or framework), so the same
// advisory at the merge-base is the same finding. Severity High and Critical are `error`, the rest `warning`.
// This report is separate from restore's NU1901-NU1904 warnings: NoWarn does not hide it.
const json = (text) => {
  const t = String(text ?? '');
  const i = t.indexOf('{');
  if (i < 0) return null;
  return JSON.parse(t.slice(i));
};

export function parse(text) {
  const doc = json(text);
  if (!doc) return [];
  if (!Array.isArray(doc.projects)) throw new Error('not `dotnet list package --format json` output (no "projects")');
  const out = [];
  const seen = new Set();
  for (const p of doc.projects) {
    for (const fw of p.frameworks ?? []) {
      for (const pkg of [...(fw.topLevelPackages ?? []), ...(fw.transitivePackages ?? [])]) {
        for (const v of pkg.vulnerabilities ?? []) {
          const advisory = String(v.advisoryurl ?? v.advisoryUrl ?? '').replace(/\/$/, '');
          const id = advisory.split('/').pop() || 'advisory';
          const key = `nuget:${pkg.id}:${id}`;
          const where = `${p.path}|${key}`;
          if (seen.has(where)) continue;
          seen.add(where);
          out.push({ rule: id, level: /^(high|critical)$/i.test(v.severity ?? '') ? 'error' : 'warning', file: p.path ?? null, line: null, message: `${pkg.id} ${pkg.resolvedVersion ?? ''} (${fw.framework}) has a ${v.severity ?? 'known'} vulnerability: ${advisory}`, snippet: null, key });
        }
      }
    }
  }
  return out;
}

export const sample = {
  text: JSON.stringify({ version: 1, parameters: '--vulnerable --include-transitive', projects: [{ path: '/r/src/Api/Api.csproj', frameworks: [{ framework: 'net10.0', topLevelPackages: [{ id: 'Some.Package', requestedVersion: '1.0.0', resolvedVersion: '1.0.0', vulnerabilities: [{ severity: 'High', advisoryurl: 'https://github.com/advisories/GHSA-aaaa-bbbb-cccc' }] }], transitivePackages: [] }] }] }),
  count: 1,
};
